import os

# ==========================================
# Directories
# ==========================================
INPUT_DIR = "./input"
METADATA_DIR = "./metadata"
WORKING_DIR = "./working/idea_13"
SUBMISSION_DIR = "./submission"

# Ensure essential directories exist
os.makedirs(WORKING_DIR, exist_ok=True)
os.makedirs(SUBMISSION_DIR, exist_ok=True)

# ==========================================
# File Paths
# ==========================================
# Metadata paths generated by the metadata script
TRAIN_PATH = os.path.join(METADATA_DIR, "train.csv")
VAL_PATH = os.path.join(METADATA_DIR, "val.csv")
TEST_PATH = os.path.join(METADATA_DIR, "test.csv")

# Final submission output path
OUTPUT_FILE = os.path.join(SUBMISSION_DIR, "submission.csv")

# ==========================================
# Global Constants
# ==========================================
SEED = 42
PROBABILITY_CLIP_EPSILON = 1e-15

# ==========================================
# Feature Columns
# ==========================================
# We hardcode the list of 192 feature names in strict alphanumeric order.
# This ensures that the column order in the DataFrames is deterministic
# and matches the order expected by the solver, preventing permutation issues.
# Features are: margin_1..64, shape_1..64, texture_1..64

_feature_types = ["margin", "shape", "texture"]
_feature_list = []

for f_type in _feature_types:
    for i in range(1, 65):
        # Construct feature name, e.g., "margin1"
        _feature_list.append(f"{f_type}{i}")

# Sort in strict alphanumeric order (e.g., margin_1, margin_10, ..., margin_2)
FEATURE_COLUMNS = sorted(_feature_list)
